    try:
        out = tslib.array_to_datetime(arr)
        # Normalize output to a comparable scalar representation
        # output should be numpy datetime64[ns] array of length 1
        return {"status":"ok","dtype":str(getattr(out,'dtype',None)),"value":str(out[0])}
    except Exception as err:
        return {"status":"error","exc_type":type(err).__name__,"message":str(err)}

inputs = [
    '1677-09-21T00:12:43.145224193',
    '1677-09-21T00:12:43.145224999',
    '1677-09-21T00:12:43.145225000'
]
res = [call_one(s) for s in inputs]

# Record separate probes for each input so harness compares deterministically
for s, r in zip(inputs, res):
